import unittest
from candidate import total_match

class TestTotalMatch(unittest.TestCase):
    def test_total_match_empty_lists(self):
        self.assertEqual(total_match([], []), [])

    def test_total_match_equal_length_lists(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hI', 'Hi']), ['hI', 'Hi'])
        self.assertEqual(total_match(['hi', 'admin'], ['hi', 'hi', 'admin', 'project']), ['hi', 'admin'])
        self.assertEqual(total_match(['hI', 'hi', 'hi'], ['hi', 'admin']), ['hI', 'hi', 'hi'])

    def test_total_match_different_length_lists(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hI', 'hi', 'hi']), ['hI', 'hi', 'hi'])
        self.assertEqual(total_match(['4'], ['1', '2', '3', '4', '5']), ['4'])

    def test_total_match_lists_with_single_strings(self):
        self.assertEqual(total_match(['a'], ['b']), ['a'])
        self.assertEqual(total_match(['b'], ['a']), ['b'])

    def test_total_match_lists_with_empty_strings(self):
        self.assertEqual(total_match(['', 'a'], ['', 'b']), ['', 'a'])
        self.assertEqual(total_match(['', 'b'], ['', 'a']), ['', 'b'])

    def test_total_match_lists_with_numbers(self):
        self.assertEqual(total_match(['4'], ['1', '2', '3', '4', '5']), ['4'])
        self.assertEqual(total_match(['1', '2', '3', '4', '5'], ['4']), ['4'])

    def test_total_match_lists_with_none_values(self):
        self.assertEqual(total_match([None], [None]), [None])
        self.assertEqual(total_match([None, 'a'], [None, 'b']), [None, 'a'])
        self.assertEqual(total_match([None, 'b'], [None, 'a']), [None, 'b'])

    def test_total_match_lists_with_mixed_types(self):
        self.assertEqual(total_match(['a', 1], ['b', 2]), ['a', 1])
        self.assertEqual(total_match(['b', 2], ['a', 1]), ['b', 2])

if __name__ == '__main__':
    unittest.main()
